import React, { useState } from 'react';
import { Link } from 'react-router-dom';

function EmotionRecommendPage() {
  const [nickname, setNickname] = useState('');
  const [inputText, setInputText] = useState('');
  const [recommendedMovie, setRecommendedMovie] = useState(null);
  const [loading, setLoading] = useState(false);

  const emotionDatabase = [
    {
      id: 'comfort',
      keywords: ['위로', '슬픔', '울적', '지침', '휴식', '힐링', '마음', '힘들', '눈물'],
      title: '싱 어 게인',
      genre: '드라마 / 음악',
      poster: '/img/00/01.jpg'
    },
    {
      id: 'thrill',
      keywords: ['짜릿', '스릴', '긴장', '액션', '시원', '답답', '스트레스'],
      title: '오디세이',
      genre: 'SF / 어드벤처',
      poster: '/img/00/04.jpg'
    },
    {
      id: 'romance',
      keywords: ['설렘', '사랑', '로맨스', '기분좋아', '행복', '재미', '달달'],
      title: '아가씨',
      genre: '매혹 / 스릴러',
      poster: '/img/00/02.jpg'
    }
  ];

  const handleRecommend = (e) => {
    e.preventDefault();
    if (!nickname.trim()) {
      alert('닉네임을 입력해주세요!');
      return;
    }
    if (!inputText.trim()) {
      alert('오늘의 감정을 간단히 적어주세요!');
      return;
    }

    setLoading(true);
    setRecommendedMovie(null);

    setTimeout(() => {
      let matched = emotionDatabase.find((item) =>
        item.keywords.some((keyword) => inputText.includes(keyword))
      );

      if (!matched) {
        matched = emotionDatabase[0];
      }

      // 💡 키워드와 감정에 맞춘 따뜻하고 섬세한 맞춤형 멘트 생성
      let customReason = "";
      if (matched.id === 'comfort') {
        customReason = `${nickname}님의 지친 마음을 포근하게 감싸 안아줄 따뜻한 음악과 위로가 가득한 작품이에요. 오늘 밤은 이 영화와 함께 깊은 휴식을 취해보세요.`;
      } else if (matched.id === 'thrill') {
        customReason = `${nickname}님의 답답했던 일상을 한방에 날려버릴 압도적인 스케일과 짜릿한 카타르시스를 선물해 드릴게요!`;
      } else {
        customReason = `${nickname}님의 하루를 포근한 설렘과 행복으로 물들여줄 매혹적이고 아름다운 이야기입니다.`;
      }

      setRecommendedMovie({
        ...matched,
        id: '665669', // 상세 페이지 연동용 ID
        reason: customReason
      });
      setLoading(false);
    }, 600);
  };

  return (
    <div className="w-full bg-[#0b090e] min-h-screen py-12 px-6 text-white flex flex-col items-center">
      <div className="w-full max-w-3xl">
        <div className="text-center mb-10">
          <span className="text-xs font-bold text-purple-400 tracking-widest uppercase">MEGABOX EMOTION CARE</span>
          <h2 className="text-3xl md:text-4xl font-black mt-2 tracking-tight">오늘의 감정에 영화를 선물하세요</h2>
          <p className="text-xs text-zinc-400 mt-2">닉네임과 오늘의 감정을 적어주시면, 따뜻한 위로와 맞춤형 영화를 추천해 드려요.</p>
        </div>

        <form onSubmit={handleRecommend} className="bg-[#131924] border border-zinc-800 rounded-2xl p-6 shadow-xl mb-10 space-y-4">
          <div>
            <label className="block text-xs font-bold text-zinc-300 mb-2">
              👤 닉네임
            </label>
            <input 
              type="text" 
              value={nickname}
              onChange={(e) => setNickname(e.target.value)}
              placeholder="사용하실 닉네임을 입력해주세요 (예: 영화광소현)" 
              className="w-full bg-zinc-900 border border-zinc-700 rounded-xl px-4 py-3 text-sm text-white focus:outline-none focus:border-purple-500 transition"
            />
          </div>

          <div>
            <label className="block text-xs font-bold text-zinc-300 mb-2">
              Q. 오늘 하루는 어떠셨나요? (예: "마음이 지치고 위로가 필요해", "짜릿한 액션이 보고 싶어")
            </label>
            <div className="flex gap-3">
              <input 
                type="text" 
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                placeholder="오늘의 감정을 자유롭게 적어보세요..." 
                className="flex-grow bg-zinc-900 border border-zinc-700 rounded-xl px-4 py-3 text-sm text-white focus:outline-none focus:border-purple-500 transition"
              />
              <button 
                type="submit" 
                className="bg-[#503396] hover:bg-[#3b2570] text-white font-bold px-6 py-3 rounded-xl text-sm transition shadow-lg shrink-0"
              >
                영화 추천받기
              </button>
            </div>
          </div>
        </form>

        {loading && (
          <div className="text-center py-16 text-purple-400 font-bold animate-pulse text-sm">
            {nickname ? `${nickname}님의 감정을 분석하여 따뜻한 위로를 준비 중입니다...` : '감정을 분석하는 중입니다...'}
          </div>
        )}

        {recommendedMovie && !loading && (
          <div className="bg-gradient-to-br from-[#1a102f] to-[#131924] border border-purple-500/30 rounded-3xl p-8 shadow-2xl flex flex-col md:flex-row items-center gap-8 animate-fade-in">
            <div className="w-48 h-64 rounded-xl bg-zinc-800 overflow-hidden shadow-lg shrink-0 border border-purple-500/20 flex items-center justify-center">
              {recommendedMovie.poster ? (
                <img src={recommendedMovie.poster} alt={recommendedMovie.title} className="w-full h-full object-cover" />
              ) : (
                <span className="text-xs text-zinc-500">포스터 이미지</span>
              )}
            </div>

            <div className="flex flex-col justify-center space-y-4 text-left w-full">
              <div>
                <span className="text-[11px] font-extrabold text-purple-300 bg-purple-950/60 px-2.5 py-1 rounded-full border border-purple-800/50">
                  {recommendedMovie.genre}
                </span>
                <h3 className="text-2xl md:text-3xl font-black text-white mt-3 mb-2">
                  {recommendedMovie.title}
                </h3>
                <p className="text-sm text-zinc-200 leading-relaxed font-medium bg-zinc-900/50 p-4 rounded-xl border border-zinc-800">
                  "{recommendedMovie.reason}"
                </p>
              </div>

              {/* 💡 상영시간표, 영화 상세히 둘러보기, 다시하기 버튼 연동 */}
              <div className="flex flex-col gap-2 pt-2">
                <div className="flex gap-3">
                  <Link 
                    to={`/movie/${recommendedMovie.id}`}
                    className="flex-grow text-center py-3 bg-[#503396] hover:bg-[#3b2570] text-white font-bold text-xs rounded-xl transition shadow-md"
                  >
                    영화 상세히 둘러보기 ✨
                  </Link>
                  <Link 
                    to="/schedule" 
                    className="flex-grow text-center py-3 bg-[#00a086] hover:bg-[#008771] text-white font-bold text-xs rounded-xl transition shadow-md"
                  >
                    상영시간표 확인하기
                  </Link>
                </div>
                
                <button 
                  onClick={() => setRecommendedMovie(null)} 
                  className="w-full py-2.5 bg-zinc-800 hover:bg-zinc-700 text-zinc-300 font-bold text-xs rounded-xl transition"
                >
                  다시하기
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default EmotionRecommendPage;
